export function graphFromManifest(nodes: FixtureNodeManifest[]): GraphAdapter {
  for (const [i, n] of nodes.entries()) {
    if (typeof n.id !== 'string' || typeof n.kind !== 'string' || typeof n.name !== 'string' || typeof n.lineage !== 'string' || typeof n.source !== 'string') {
      throw new Error(`CALIBRATION_FIXTURE_INVALID: graph.nodes[${i}] is missing required fields (id/kind/name/lineage/source)`);
    }
  }
  const materialized: GraphNode[] = nodes.map((n) => ({
    id: n.id, kind: n.kind, name: n.name, file: n.file, line: n.line,
    lineage: n.lineage, source: n.source, data: n.data,
  }));

